create table public.cda_orc_tipos_projeto(id uuid primary key default gen_random_uuid(),codigo integer generated always as identity unique,nome text not null unique,descricao text,ativo boolean not null default true,criado_em timestamptz not null default now());
create table public.cda_orc_projetos(id uuid primary key default gen_random_uuid(),nome text not null check(length(trim(nome))>0),descricao text,ativo boolean not null default true,criado_em timestamptz not null default now());
create table public.cda_orc_projeto_tipos(id uuid primary key default gen_random_uuid(),projeto_id uuid not null references public.cda_orc_projetos(id),tipo_id uuid not null references public.cda_orc_tipos_projeto(id),ativo boolean not null default true,parametros jsonb not null default '{}',unique(projeto_id,tipo_id));
create table public.cda_orc_projeto_participantes(id uuid primary key default gen_random_uuid(),projeto_id uuid not null references public.cda_orc_projetos(id),pessoa_id uuid not null references public.cda_orc_pessoas(id),ativo boolean not null default true,unique(projeto_id,pessoa_id));
alter table public.cda_orc_tipos_projeto enable row level security;grant select,insert,update on public.cda_orc_tipos_projeto to authenticated;revoke all on public.cda_orc_tipos_projeto from anon;create policy leitura on public.cda_orc_tipos_projeto for select to authenticated using (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))));create policy inclusao on public.cda_orc_tipos_projeto for insert to authenticated with check (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));create policy edicao on public.cda_orc_tipos_projeto for update to authenticated using (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita')) with check (exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and (e.is_admin or 'orcamento_vendas'=any(e.projetos))) and exists(select 1 from public.equipe e where lower(e.email)=lower(auth.jwt()->>'email') and coalesce(e.permissao,'leitura_escrita')='leitura_escrita'));
