grant usage,select on sequence public.cda_orc_tipos_projeto_codigo_seq to authenticated;
insert into public.cda_orc_tipos_projeto(nome,descricao) values ('Shows/Eventos','Orçamentos de shows e eventos'),('E-Commerce','Orçamentos de vendas digitais'),('Private Label','Orçamentos de produção para terceiros');
insert into public.cda_orc_projetos(nome) values ('Projeto Sandy Junior 2027');
insert into public.cda_orc_projeto_tipos(projeto_id,tipo_id,parametros) select p.id,t.id,case when t.nome='Shows/Eventos' then jsonb_build_object('publico_total',400000,'shows',10,'conversoes',jsonb_build_array(5,7,9),'situacao','em_desenvolvimento') else jsonb_build_object('situacao','em_espera') end from public.cda_orc_projetos p cross join public.cda_orc_tipos_projeto t where p.nome='Projeto Sandy Junior 2027';
insert into public.cda_orc_projeto_participantes(projeto_id,pessoa_id) select p.id,x.id from public.cda_orc_projetos p join public.cda_orc_pessoas x on x.nome in ('Sandy & Junior','Ciclo Arte','Dimona') where p.nome='Projeto Sandy Junior 2027';